import{_ as a,o as t,c as r,a2 as s}from"./chunks/framework.C7GIOALF.js";const p=JSON.parse('{"title":"Creature Feature Rules","description":"","frontmatter":{},"headers":[],"relativePath":"formats/creature-feature/rules.md","filePath":"formats/creature-feature/rules.md","lastUpdated":null}'),n={name:"formats/creature-feature/rules.md"};function o(i,e,l,u,c,d){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="creature-feature-rules" tabindex="-1">Creature Feature Rules <a class="header-anchor" href="#creature-feature-rules" aria-label="Permalink to &quot;Creature Feature Rules&quot;">​</a></h1><p><a href="./">Creature Feature parent page</a> · <strong>Local rules: Pegasus Loft</strong></p><p>Creature Feature is a local Pegasus Loft constructed format that uses normal Magic gameplay, but adds deck-building pressure around creature density and shared creature types.</p><h2 id="core-rules" tabindex="-1">Core Rules <a class="header-anchor" href="#core-rules" aria-label="Permalink to &quot;Core Rules&quot;">​</a></h2><ul><li>Decks have a <strong>60-card minimum</strong>.</li><li>At least <strong>half of the deck</strong> must be creature cards, rounded up.</li><li>At least <strong>two thirds of the creature cards</strong> in the deck must share a creature type, rounded up.</li><li>Games are played as normal Magic unless the event organizer announces an additional house rule.</li><li>Use normal constructed deck-building rules unless the event organizer announces otherwise.</li></ul><h2 id="creature-type-requirement" tabindex="-1">Creature Type Requirement <a class="header-anchor" href="#creature-type-requirement" aria-label="Permalink to &quot;Creature Type Requirement&quot;">​</a></h2><p>Choose one creature type as the deck&#39;s featured type. A creature card counts toward the shared-type requirement if its Oracle creature types include the featured type.</p><p>For example:</p><ul><li>A 60-card deck needs at least 30 creature cards.</li><li>If that deck has 30 creature cards, at least 20 of those creatures must share the featured type.</li><li>If that deck has 31 creature cards, at least 21 of those creatures must share the featured type.</li></ul><p>Creatures with multiple creature types can count for any type they have. Changelings count as having every creature type unless the event organizer has separately banned or restricted that interaction.</p><h2 id="temporary-type-bans" tabindex="-1">Temporary Type Bans <a class="header-anchor" href="#temporary-type-bans" aria-label="Permalink to &quot;Temporary Type Bans&quot;">​</a></h2><p>When a creature type wins a Creature Feature tournament, that creature type should be temporarily banned for the next four weeks.</p><p>The goal is to keep dominant types from repeating every event, especially creature types with deep tribal support such as Eldrazi or Sliver. After the temporary ban expires, the type becomes legal again unless it wins another event.</p><h2 id="negative-creature-type-hate" tabindex="-1">Negative Creature-Type Hate <a class="header-anchor" href="#negative-creature-type-hate" aria-label="Permalink to &quot;Negative Creature-Type Hate&quot;">​</a></h2><p>Cards that negatively target creature types are banned.</p><p>This includes cards whose main purpose is to punish, remove, shrink, prevent, or otherwise disadvantage a named creature type. Color hate, mana-value hate, graveyard hate, artifact hate, and other non-type-specific answers are still legal unless they are banned by another rule.</p><p>Use this as the practical test: if the card asks a player to choose or name a creature type and then harms that type or gives protection from that type, it should not be played in Creature Feature.</p><h2 id="event-notes" tabindex="-1">Event Notes <a class="header-anchor" href="#event-notes" aria-label="Permalink to &quot;Event Notes&quot;">​</a></h2><ul><li>Keep a visible list of currently banned creature types and the date each ban expires.</li><li>Record the winning featured type after each event.</li><li>If a winning deck uses multiple creature types heavily, ban the type that satisfied the two-thirds requirement.</li><li>If the event uses sideboards, the deck should still satisfy the creature-count and shared-type requirements after sideboarding.</li></ul><h2 id="before-an-event" tabindex="-1">Before an event <a class="header-anchor" href="#before-an-event" aria-label="Permalink to &quot;Before an event&quot;">​</a></h2><p>The organizer must announce the permitted card pool, any additional house rules, whether sideboards are used, and the current temporary type bans. The existing rules do not select a sanctioned constructed format&#39;s legality list automatically.</p><p>A temporary type ban needs a clear event interpretation: does it prohibit choosing that featured type, or prohibit every card with that type? This matters especially for changelings. That decision has not been recorded in the local rules.</p><h2 id="setup-play-and-victory" tabindex="-1">Setup, play, and victory <a class="header-anchor" href="#setup-play-and-victory" aria-label="Permalink to &quot;Setup, play, and victory&quot;">​</a></h2><p>After checking deck legality, play normal Magic using the event&#39;s announced structure. For an ordinary two-player constructed game, each player starts at 20 life, draws seven, uses normal mulligans, and the starting player skips their first draw. Normal turn structure, combat, and win/loss conditions apply. Multiplayer events use normal multiplayer setup instead.</p><p>No special victory condition is added by Creature Feature. After each event, record the winner&#39;s declared featured type and the expiration of its four-week ban.</p><h2 id="provenance" tabindex="-1">Provenance <a class="header-anchor" href="#provenance" aria-label="Permalink to &quot;Provenance&quot;">​</a></h2><p>These are the local Pegasus Loft rules recorded in this repository. They are not an official Wizards format or a rule imported from another creature-type format.</p>',27)])])}const y=a(n,[["render",o]]);export{p as __pageData,y as default};
